	// on itself, which is how this package already treats Date and RegExp.
	switch rv.Kind() {
	case reflect.Pointer, reflect.UnsafePointer, reflect.Chan:
		// An interface holding a pointer compares by type and address.
		return v, true
	case reflect.Func:
		return nil, false
